"use client";

import React, { useMemo, useState } from "react";

const LOGO_SRC = "data:image/png;base64,";
const SIGMA = 5.670374419e-8;

function fmt(value: number, digits = 0) {
  if (!Number.isFinite(value)) return "—";
  return value.toLocaleString(undefined, { maximumFractionDigits: digits });
}

function calcFlux(tempK: number, sinkK: number, emissivity: number, effectiveness: number) {
  return Math.max(1, emissivity * SIGMA * (Math.pow(tempK, 4) - Math.pow(sinkK, 4)) * effectiveness);
}

function SliderRow({ label, value, min, max, step, unit, onChange }: {
  label: string;
  value: number;
  min: number;
  max: number;
  step: number;
  unit?: string;
  onChange: (v: number) => void;
}) {
  return (
    <label className="sliderRow">
      <div className="sliderTop">
        <span>{label}</span>
        <div className="numberBox">
          <input
            type="number"
            value={value}
            min={min}
            max={max}
            step={step}
            onChange={(e) => onChange(Number(e.target.value))}
          />
          {unit && <em>{unit}</em>}
        </div>
      </div>
      <input
        type="range"
        value={value}
        min={min}
        max={max}
        step={step}
        onChange={(e) => onChange(Number(e.target.value))}
      />
      <div className="scale"><span>{min}</span><span>{value}</span><span>{max}</span></div>
    </label>
  );
}

function MetricCard({ title, value, sub }: { title: string; value: string; sub?: string }) {
  return <div className="metricCard"><span>{title}</span><strong>{value}</strong>{sub && <small>{sub}</small>}</div>;
}

function Bar({ label, value, max }: { label: string; value: number; max: number }) {
  const height = Math.max(4, Math.min(100, (value / max) * 100));
  return (
    <div className="barWrap">
      <div className="barPlot"><div className="bar" style={{ height: `${height}%` }} /></div>
      <b>{fmt(value, 0)}</b>
      <span>{label}</span>
    </div>
  );
}

export default function ThermalStudioPage() {
  const [tab, setTab] = useState("thermal");
  const [itLoad, setItLoad] = useState(1000);
  const [radiatorTemp, setRadiatorTemp] = useState(323);
  const [sinkTemp, setSinkTemp] = useState(3);
  const [emissivity, setEmissivity] = useState(0.9);
  const [effectiveness, setEffectiveness] = useState(0.9);
  const [arealDensity, setArealDensity] = useState(2.0);
  const [activeOverheadPct, setActiveOverheadPct] = useState(5.0);
  const [passiveOverheadPct, setPassiveOverheadPct] = useState(0.2);
  const [activeHardwarePct, setActiveHardwarePct] = useState(35);
  const [passiveHardwarePct, setPassiveHardwarePct] = useState(15);
  const [orbit, setOrbit] = useState("LEO");

  const results = useMemo(() => {
    const baseFlux = calcFlux(radiatorTemp, sinkTemp, emissivity, effectiveness);
    const computeHeat = itLoad;
    const baseArea = computeHeat * 1000 / baseFlux;
    const baseRadMass = baseArea * arealDensity;
    const activeOverhead = itLoad * activeOverheadPct / 100;
    const passiveOverhead = itLoad * passiveOverheadPct / 100;
    const activeHeat = itLoad + activeOverhead;
    const passiveHeat = itLoad + passiveOverhead;
    const activeArea = activeHeat * 1000 / baseFlux;
    const passiveArea = passiveHeat * 1000 / baseFlux;
    const activeRadMass = activeArea * arealDensity;
    const passiveRadMass = passiveArea * arealDensity;
    const activeHardware = activeRadMass * activeHardwarePct / 100;
    const passiveHardware = passiveRadMass * passiveHardwarePct / 100;
    return {
      baseFlux, computeHeat, baseArea, baseRadMass,
      activeOverhead, passiveOverhead, activeHeat, passiveHeat,
      activeArea, passiveArea, activeRadMass, passiveRadMass,
      activeHardware, passiveHardware,
      activeTotalMass: activeRadMass + activeHardware,
      passiveTotalMass: passiveRadMass + passiveHardware,
      totalFacilityPower: itLoad + activeOverhead,
      massSavings: activeRadMass + activeHardware - (passiveRadMass + passiveHardware),
      powerSavings: activeOverhead - passiveOverhead,
      areaSavings: activeArea - passiveArea,
    };
  }, [itLoad, radiatorTemp, sinkTemp, emissivity, effectiveness, arealDensity, activeOverheadPct, passiveOverheadPct, activeHardwarePct, passiveHardwarePct]);

  const barMax = Math.max(results.activeArea, results.passiveArea, results.activeTotalMass, results.passiveTotalMass) * 1.15;
  const tabs = [
    ["dashboard", "Dashboard"], ["thermal", "Thermal Calculator"], ["orbit", "Orbit Effects"], ["radiator", "Radiator Sizing"], ["architecture", "Architecture Comparison"], ["trade", "Trade Study"], ["materials", "Materials"], ["reports", "Reports"]
  ];

  return (
    <main className="studioShell">
      <header className="studioHeader">
        <div className="brandBlock"><img src={LOGO_SRC} alt="Nuwatts logo" /><p>Powering the next frontier of compute</p></div>
        <div className="titleBlock"><h1>Nuwatts Thermal Studio</h1><p>Orbital Thermal Engineering Suite v1.0</p></div>
        <div className="headerActions"><span>Save case</span><span>Load case</span><span>Export PDF</span></div>
      </header>

      <nav className="tabs">
        {tabs.map(([key, label]) => <button key={key} onClick={() => setTab(key)} className={tab === key ? "active" : ""}>{label}</button>)}
      </nav>

      <section className="workspace">
        <aside className="panel controls">
          <h2>Input parameters</h2>
          <SliderRow label="Thermal design power" value={itLoad} min={100} max={10000} step={50} unit="kW" onChange={setItLoad} />
          <SliderRow label="Radiator temperature" value={radiatorTemp} min={273} max={500} step={1} unit="K" onChange={setRadiatorTemp} />
          <SliderRow label="Effective sink temperature" value={sinkTemp} min={3} max={300} step={1} unit="K" onChange={setSinkTemp} />
          <SliderRow label="Radiator emissivity" value={emissivity} min={0.5} max={0.98} step={0.01} onChange={setEmissivity} />
          <SliderRow label="Heat rejection effectiveness" value={effectiveness} min={0.2} max={1} step={0.01} onChange={setEffectiveness} />
          <SliderRow label="Radiator areal density" value={arealDensity} min={1} max={20} step={0.1} unit="kg/m²" onChange={setArealDensity} />
          <button className="reset" onClick={() => { setItLoad(1000); setRadiatorTemp(323); setSinkTemp(3); setEmissivity(0.9); setEffectiveness(0.9); setArealDensity(2); setActiveOverheadPct(5); setPassiveOverheadPct(0.2); }}>Reset to defaults</button>
        </aside>

        <section className="mainColumn">
          <div className="panel heroPanel">
            <div><h2>{tab === "thermal" ? "Thermal Calculator" : tabs.find(t => t[0] === tab)?.[1]}</h2><p>Interactive first-order trade study for orbital compute thermal infrastructure.</p></div>
            <select value={orbit} onChange={e => setOrbit(e.target.value)}><option>LEO</option><option>SSO</option><option>GEO</option><option>Cislunar</option><option>Deep space</option></select>
          </div>

          <div className="cards">
            <MetricCard title="Required radiator area" value={`${fmt(results.baseArea, 0)} m²`} />
            <MetricCard title="Radiator mass estimate" value={`${fmt(results.baseRadMass, 0)} kg`} />
            <MetricCard title="Heat rejection flux" value={`${fmt(results.baseFlux, 0)} W/m²`} />
            <MetricCard title="Active cooling overhead" value={`${fmt(results.activeOverhead, 1)} kW`} />
          </div>

          <div className="panel chartPanel">
            <h2>Architecture comparison</h2>
            <div className="barChart">
              <Bar label="Active area" value={results.activeArea} max={barMax} />
              <Bar label="Passive area" value={results.passiveArea} max={barMax} />
              <Bar label="Active mass" value={results.activeTotalMass} max={barMax} />
              <Bar label="Passive mass" value={results.passiveTotalMass} max={barMax} />
            </div>
          </div>

          <div className="comparisonGrid">
            <div className="panel compareCard activeArch"><h2>Conventional active architecture</h2>
              <p>Centralized pumped thermal transport.</p>
              <dl><dt>Total heat to reject</dt><dd>{fmt(results.activeHeat, 1)} kW</dd><dt>Radiator area</dt><dd>{fmt(results.activeArea, 0)} m²</dd><dt>Total thermal subsystem mass</dt><dd>{fmt(results.activeTotalMass, 0)} kg</dd><dt>Cooling overhead</dt><dd>{fmt(results.activeOverhead, 1)} kW</dd></dl>
              <SliderRow label="Active overhead" value={activeOverheadPct} min={0} max={25} step={0.5} unit="%" onChange={setActiveOverheadPct} />
              <SliderRow label="Active hardware mass" value={activeHardwarePct} min={0} max={100} step={1} unit="%" onChange={setActiveHardwarePct} />
            </div>
            <div className="panel compareCard passiveArch"><h2>Nuwatts passive architecture</h2>
              <p>Distributed passive thermal transport layer concept.</p>
              <dl><dt>Total heat to reject</dt><dd>{fmt(results.passiveHeat, 1)} kW</dd><dt>Radiator area</dt><dd>{fmt(results.passiveArea, 0)} m²</dd><dt>Total thermal subsystem mass</dt><dd>{fmt(results.passiveTotalMass, 0)} kg</dd><dt>Cooling overhead</dt><dd>{fmt(results.passiveOverhead, 1)} kW</dd></dl>
              <SliderRow label="Passive overhead" value={passiveOverheadPct} min={0} max={5} step={0.1} unit="%" onChange={setPassiveOverheadPct} />
              <SliderRow label="Passive hardware mass" value={passiveHardwarePct} min={0} max={100} step={1} unit="%" onChange={setPassiveHardwarePct} />
            </div>
          </div>
        </section>

        <aside className="panel sidePanel">
          <h2>System summary</h2>
          <dl><dt>Orbit environment</dt><dd>{orbit}</dd><dt>IT load</dt><dd>{fmt(itLoad, 0)} kW</dd><dt>Radiator temperature</dt><dd>{fmt(radiatorTemp, 0)} K</dd><dt>Radiator area</dt><dd>{fmt(results.baseArea, 0)} m²</dd><dt>Mass savings estimate</dt><dd className="good">{fmt(results.massSavings, 0)} kg</dd><dt>Overhead reduction</dt><dd className="good">{fmt(results.powerSavings, 1)} kW</dd></dl>
          <div className="note">Calculations use Stefan–Boltzmann radiation with emissivity and effectiveness losses. Results are for preliminary sizing only.</div>
        </aside>
      </section>

      <style jsx global>{`
        :root { --bg:#050b14; --panel:#0d1726; --panel2:#111f33; --line:rgba(255,255,255,.12); --text:#eef6ff; --muted:#9db0c8; --blue:#46a7ff; --cyan:#21d1c8; --green:#76e36b; }
        body { margin:0; background:radial-gradient(circle at 20% 0%, #132743 0%, var(--bg) 44%, #03060b 100%); color:var(--text); font-family:Inter,system-ui,-apple-system,Segoe UI,Arial,sans-serif; }
        * { box-sizing:border-box; }
        .studioShell { min-height:100vh; }
        .studioHeader { display:grid; grid-template-columns:280px 1fr 280px; gap:24px; align-items:center; padding:22px 32px; border-bottom:1px solid var(--line); background:rgba(0,0,0,.28); }
        .brandBlock img { width:170px; max-height:75px; object-fit:contain; object-position:left center; display:block; }
        .brandBlock p,.titleBlock p { margin:6px 0 0; color:var(--muted); }
        .titleBlock { text-align:center; } .titleBlock h1 { margin:0; text-transform:uppercase; letter-spacing:.05em; font-size:2rem; } .titleBlock p { color:var(--blue); font-size:1.05rem; }
        .headerActions { display:flex; justify-content:flex-end; gap:18px; color:var(--muted); font-size:.9rem; }
        .tabs { display:flex; overflow:auto; border-bottom:1px solid var(--line); background:rgba(255,255,255,.03); }
        .tabs button { appearance:none; border:0; border-right:1px solid var(--line); background:transparent; color:var(--text); padding:18px 24px; font-weight:700; cursor:pointer; text-transform:uppercase; letter-spacing:.03em; }
        .tabs button.active { color:var(--blue); background:rgba(70,167,255,.12); box-shadow:inset 0 -2px 0 var(--blue); }
        .workspace { display:grid; grid-template-columns:330px 1fr 300px; gap:16px; padding:22px; }
        .panel,.metricCard { background:linear-gradient(180deg, rgba(17,31,51,.96), rgba(8,17,30,.96)); border:1px solid var(--line); border-radius:12px; box-shadow:0 18px 60px rgba(0,0,0,.25); }
        .panel { padding:20px; } h2 { margin:0 0 16px; font-size:1rem; text-transform:uppercase; letter-spacing:.04em; }
        .sliderRow { display:block; margin:0 0 22px; color:var(--text); } .sliderTop { display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:8px; }
        .numberBox { display:flex; align-items:center; border:1px solid var(--line); border-radius:8px; overflow:hidden; background:rgba(255,255,255,.04); }
        .numberBox input { width:92px; padding:8px; background:transparent; color:var(--text); border:0; font:inherit; text-align:right; } .numberBox em { padding:8px; color:var(--muted); font-style:normal; border-left:1px solid var(--line); }
        input[type=range] { width:100%; accent-color:var(--blue); } .scale { display:flex; justify-content:space-between; font-size:.78rem; color:var(--muted); }
        .reset { width:100%; padding:12px 14px; border:1px solid var(--blue); border-radius:8px; color:var(--blue); background:rgba(70,167,255,.08); font-weight:800; cursor:pointer; }
        .mainColumn { display:grid; gap:16px; } .heroPanel { display:flex; justify-content:space-between; align-items:center; gap:20px; } .heroPanel p { margin:0; color:var(--muted); }
        select { color:var(--text); background:#071322; border:1px solid var(--line); border-radius:8px; padding:10px 12px; }
        .cards { display:grid; grid-template-columns:repeat(4,1fr); gap:12px; } .metricCard { padding:18px; min-height:115px; } .metricCard span { color:var(--muted); display:block; min-height:34px; } .metricCard strong { display:block; font-size:1.85rem; margin-top:12px; } .metricCard small { color:var(--muted); }
        .barChart { height:280px; display:grid; grid-template-columns:repeat(4,1fr); gap:24px; align-items:end; padding:20px 20px 0; border-top:1px solid var(--line); }
        .barWrap { height:240px; display:grid; grid-template-rows:1fr 24px 24px; align-items:end; justify-items:center; color:var(--muted); } .barPlot { height:180px; width:66px; display:flex; align-items:end; border-left:1px solid var(--line); border-bottom:1px solid var(--line); padding-left:10px; }
        .bar { width:40px; min-height:4px; border-radius:6px 6px 0 0; background:linear-gradient(180deg,var(--cyan),var(--blue)); transition:height .15s ease; } .barWrap b { color:var(--text); }
        .comparisonGrid { display:grid; grid-template-columns:1fr 1fr; gap:16px; } .compareCard p { color:var(--muted); margin-top:-6px; }
        dl { margin:0; } dt,dd { margin:0; padding:10px 0; border-bottom:1px solid var(--line); } dt { color:var(--muted); float:left; } dd { text-align:right; font-weight:800; } .good { color:var(--green); }
        .sidePanel .note { margin-top:18px; padding:14px; border:1px solid var(--line); border-radius:8px; color:var(--muted); line-height:1.5; }
        @media(max-width:1200px){ .studioHeader,.workspace{ grid-template-columns:1fr; } .titleBlock{ text-align:left; } .headerActions{ justify-content:flex-start; } .cards,.comparisonGrid{ grid-template-columns:1fr 1fr; } }
        @media(max-width:760px){ .cards,.comparisonGrid{ grid-template-columns:1fr; } .barChart{ grid-template-columns:repeat(2,1fr); height:auto; } .tabs button{ padding:14px; font-size:.82rem; } }
      `}</style>
    </main>
  );
}
